+    pub(super) frame: Frame,
+    shape: Shape,
+    profile: Arc<Profile>,
+}
+
+impl std::fmt::Debug for Cut {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        f.debug_struct("Cut").field("frame", &self.frame).finish_non_exhaustive()
+    }
