+                (Some(cot), _) => SdfTool::Taper { r: op.radius, cot },
+                (None, Some(corner)) => SdfTool::BullNose { r: op.radius, corner, flank },
+                (None, None) if op.ball => SdfTool::Shanked { r: op.radius, shank: flank },
+                _ => SdfTool::Flat { r: op.radius, flank },
+            };
