+fn minus(spans: Vec<Span>, remove: Span) -> Vec<Span> {
+    let mut out = Vec::new();
+    for (lo, hi) in spans {
+        if remove.1 <= lo || remove.0 >= hi {
+            out.push((lo, hi));
+            continue;
+        }
+        if remove.0 > lo {
+            out.push((lo, remove.0));
+        }
+        if remove.1 < hi {
+            out.push((remove.1, hi));
+        }
+    }
+    out
